const outputPath = path.join(__dirname, '..', 'frontend', 'config', 'guide-content', 'it', 'create-etsy-worksheet-bundles.ts');
fs.writeFileSync(outputPath, content, 'utf8');
console.log('Written:', outputPath);
console.log('Size:', fs.statSync(outputPath).size, 'bytes');

// Verify no \\uXXXX escape sequences in the output
const written = fs.readFileSync(outputPath, 'utf8');
const escapeMatches = written.match(/\\u[0-9a-fA-F]{4}/g);
if (escapeMatches) {
  console.error('WARNING: Found \\uXXXX escapes:', [...new Set(escapeMatches)]);
} else {
  console.log('OK: No \\uXXXX escape sequences found');
}

// Check titleTag length
const titleMatch = written.match(/titleTag:\s*'([^']+)'/);
if (titleMatch) {
  console.log('titleTag:', titleMatch[1], '(' + titleMatch[1].length + ' chars)');
}

// Check metaDescription length
const metaMatch = written.match(/metaDescription:\s*'([^']+)'/);
if (metaMatch) {
  console.log('metaDescription: (' + metaMatch[1].length + ' chars)');
}

// Check refund FAQ
if (written.includes('non offriamo rimborsi')) {
  console.log('OK: Refund policy FAQ present with "non offriamo rimborsi"');
} else {
  console.error('WARNING: Missing refund policy text');
}
